<template><van-popup v-model:show="visible" position="bottom" round class="language-popup"><div class="handle"/><header><h2>{{title}}</h2><button type="button" @click="visible=false"><van-icon name="cross"/></button></header><button v-for="language in languages" :key="language.code" class="option" type="button" @click="select(language)"><span>{{language.label}}</span><van-icon v-if="language.code===modelValue" name="success"/></button></van-popup></template>
<script setup>import{computed}from'vue';const props=defineProps({show:Boolean,title:{type:String,default:'语言'},languages:{type:Array,default:()=>[]},modelValue:String});const emit=defineEmits(['update:show','update:modelValue','select']);const visible=computed({get:()=>props.show,set:v=>emit('update:show',v)});function select(x){emit('update:modelValue',x.code);emit('select',x);visible.value=false}</script>
<style scoped>.language-popup{padding:8px 16px 16px;background:#F2F3F5;overflow:hidden}.handle{width:40px;height:4px;margin:0 auto 8px;border-radius:100px;background:#C9CDD4}.language-popup header{position:relative;height:48px;display:flex;align-items:center;justify-content:center}.language-popup h2{margin:0;color:#1D2129;font:600 18px/24px "PingFang SC",sans-serif}.language-popup header button{position:absolute;top:2px;right:-8px;width:44px;height:44px;border:0;color:#86909C;background:#fff;border-radius:50%}.option{width:100%;min-height:48px;padding:0 8px;display:flex;align-items:center;justify-content:space-between;border:0;border-bottom:1px solid #F2F3F5;background:#fff;color:#1D2129;font:400 16px/24px "PingFang SC",sans-serif;text-align:left}.option:first-of-type{border-radius:12px 12px 0 0}.option:last-of-type{border-radius:0 0 12px 12px}.option .van-icon{color:#00AAA6;font-size:20px}</style>
